package com.saludintegral.medico.services;
import org.springframework.stereotype.Service;import java.util.*;import com.saludintegral.medico.model.HorarioMedico;import com.saludintegral.medico.repository.*;import com.saludintegral.medico.dto.HorarioRequest;@Service public class HorarioService{final HorarioRepository r;final MedicoRepository m;public HorarioService(HorarioRepository r,MedicoRepository m){this.r=r;this.m=m;}public List<HorarioMedico> all(){return r.findAll();}public HorarioMedico get(Long id){return r.findById(id).orElseThrow(()->new NoSuchElementException("Horario no encontrado: "+id));}public HorarioMedico save(HorarioRequest x){if(!m.existsById(x.idMedico()))throw new NoSuchElementException("Médico no encontrado");if(!x.horaFin().isAfter(x.horaInicio()))throw new IllegalArgumentException("Hora fin debe ser posterior a inicio");HorarioMedico h=new HorarioMedico();h.idMedico=x.idMedico();h.diaSemana=x.diaSemana();h.horaInicio=x.horaInicio();h.horaFin=x.horaFin();return r.save(h);}public void delete(Long id){r.delete(get(id));}}
